validator:
function validate([operations]) {
  if (!Array.isArray(operations) || operations.length < 1 || operations.length > 100) return 'operations needs 1 to 100 statements.';
  const allowed = new Set(['++X', 'X++', '--X', 'X--']);
  if (operations.some(op => !allowed.has(op))) return 'Each statement is "++X", "X++", "--X" or "X--".';
  return null;
}

reference:
function finalValueAfterOperations(operations) {
  let x = 0;
  for (const operation of operations) {
    if (operation[1] === '+') {
      x++;
    } else {
      x--;
    }
  }
  return x;
}

brute:
function finalValueAfterOperations(operations) {
  const effect = { '++X': 1, 'X++': 1, '--X': -1, 'X--': -1 };
  return operations.reduce((total, op) => total + effect[op], 0);
}

generator:
function generate(rand, size) {
  const n = size === 'large' ? 100 : 1 + Math.floor(rand() * 8);
  const plus = rand();
  const ops = [];
  for (let i = 0; i < n; i++) {
    const up = rand() < plus;
    const prefix = rand() < 0.5;
    ops.push(up ? (prefix ? '++X' : 'X++') : (prefix ? '--X' : 'X--'));
  }
  return [ops];
}
